import{R as e,e as a,f as n,U as o}from"./chunks/framework.ywem4qy5.js";const d=JSON.parse('{"title":"PayPal","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/payments/paypal.md","filePath":"integrations/payments/paypal.md","lastUpdated":1775908585000}'),r={name:"integrations/payments/paypal.md"};function i(l,t,s,p,g,h){return a(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="paypal" tabindex="-1">PayPal <a class="header-anchor" href="#paypal" aria-label="Permalink to &quot;PayPal&quot;">​</a></h1><p>Follow the below steps to connect to the PayPal API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Payments</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>PayPal</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-paypal-api" tabindex="-1">Step 2. Connect to the PayPal API <a class="header-anchor" href="#step-2-connect-to-the-paypal-api" aria-label="Permalink to &quot;Step 2. Connect to the PayPal API&quot;">​</a></h3><ol><li>Go to your <a href="https://developer.paypal.com/developer/applications/" target="_blank">PayPal REST API</a> application settings.</li><li>Select either <strong>Sandbox</strong> or <strong>Live</strong> and click the <strong>Create App</strong> button.</li><li>Enter a <strong>App Name</strong> and select <strong>Merchant</strong> for the <strong>App Type</strong>.</li><li>Copy the <strong>Client ID</strong> from PayPal and paste in the <strong>Client ID</strong> field in Formie.</li><li>Copy the <strong>Secret</strong> from PayPal and paste in the <strong>Client Secret</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-field-setting" tabindex="-1">Step 4. Field Setting <a class="header-anchor" href="#step-4-field-setting" aria-label="Permalink to &quot;Step 4. Field Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Add a <strong>Payment</strong> field to your form.</li><li>Select PayPal for the <strong>Payment Provider</strong>.</li></ol><p>The PayPal payment integration supports only once-off payments.</p>',11)])])}const P=e(r,[["render",i]]);export{d as __pageData,P as default};
